/**
 * Injected script to access the window's `CKEDITOR` instance.
 *
 * Appends payload's `html` into the editor with ID `editorId`. Falls back
 * to using the active editor if `editor` is not found, and will also
 * fall back to using `plain` instead of `html` if `html` is not in the payload`.
 *
 * See: https://stackoverflow.com/questions/9515704 (Method #1)
 * Linked from: https://stackoverflow.com/questions/59804297
 *
 * CK Editor docs:
 * https://ckeditor.com/docs/ckeditor4/latest/api/CKEDITOR_editor.html#method-insertHtml
 * https://ckeditor.com/docs/ckeditor4/latest/api/CKEDITOR_dom_range.html
 */

(() => {
  try {
    const { html, plain, editorId } = JSON.parse(
      document.currentScript?.dataset.params ?? "{}",
    );

    const cke = CKEDITOR;
    const editor = cke.instances[editorId] ?? cke.currentInstance;
    if (!editor) return;

    editor.fire("focus");

    if (html) {
      const hasText = !!editor.getData();
      if (hasText) {
        const range = editor.createRange();
        range.selectNodeContents(editor.editable());
        range.collapse();
        range.select();
        editor.insertHtml(`<br>${html}`, "html", range);
      } else {
        editor.insertHtml(`${html}`);
      }
    } else if (plain) {
      editor.insertText(`${plain}`);
    }
  } catch {}
})();
